// Headless-Chromium CDP driver: loads index.html from file://, collects
// console errors / exceptions, steps the time-of-day slider, screenshots.
const { spawn } = require('child_process');
const fs = require('fs');
const http = require('http');

const FILE = '/tmp/ocb/task-1-voxel-zen-garden/space-bunny/index.html';
const URL = 'file://' + FILE;
const PORT = 9333;
const OUT = '/tmp/opencode/shots';
const TIMES = [
  ['dawn', 6.3],
  ['noon', 12.4],
  ['dusk', 18.3],
  ['night', 22.5],
];

fs.mkdirSync(OUT, { recursive: true });

const chrome = spawn('chromium', [
  '--headless=new', '--no-sandbox', '--disable-dev-shm-usage',
  '--enable-unsafe-swiftshader', '--use-gl=angle', '--use-angle=swiftshader',
  '--hide-scrollbars', '--mute-audio',
  '--window-size=1280,800',
  '--remote-debugging-port=' + PORT,
  'about:blank',
], { stdio: 'ignore' });

const sleep = ms => new Promise(r => setTimeout(r, ms));

function getJSON(path) {
  return new Promise((res, rej) => {
    http.get({ host: '127.0.0.1', port: PORT, path }, r => {
      let d = ''; r.on('data', c => d += c); r.on('end', () => { try { res(JSON.parse(d)); } catch (e) { rej(e); } });
    }).on('error', rej);
  });
}

(async () => {
  let list = null;
  for (let i = 0; i < 60; i++) {
    try { list = await getJSON('/json/list'); if (list && list.length) break; } catch (e) {}
    await sleep(300);
  }
  if (!list || !list.length) { console.error('no chromium targets'); chrome.kill(); process.exit(1); }
  const page = list.find(t => t.type === 'page') || list[0];
  const ws = new WebSocket(page.webSocketDebuggerUrl);

  let id = 0;
  const pending = new Map();
  const logs = [];
  const errors = [];

  ws.onmessage = ev => {
    const m = JSON.parse(ev.data);
    if (m.id && pending.has(m.id)) { pending.get(m.id)(m); pending.delete(m.id); return; }
    if (m.method === 'Runtime.consoleAPICalled') {
      const txt = (m.params.args || []).map(a => a.value !== undefined ? a.value : (a.description || a.type)).join(' ');
      logs.push('[' + m.params.type + '] ' + txt);
      if (m.params.type === 'error') errors.push(txt);
    }
    if (m.method === 'Runtime.exceptionThrown') {
      const d = m.params.exceptionDetails;
      errors.push('EXCEPTION: ' + (d.exception && d.exception.description || d.text));
    }
    if (m.method === 'Log.entryAdded' && m.params.entry.level === 'error') {
      errors.push('LOG: ' + m.params.entry.text);
    }
  };

  const send = (method, params) => new Promise(res => {
    const mid = ++id;
    pending.set(mid, res);
    ws.send(JSON.stringify({ id: mid, method, params: params || {} }));
  });

  await new Promise(r => ws.onopen = r);
  await send('Runtime.enable');
  await send('Log.enable');
  await send('Page.enable');
  await send('Emulation.setDeviceMetricsOverride', { width: 1280, height: 800, deviceScaleFactor: 1, mobile: false });

  await send('Page.navigate', { url: URL });
  await sleep(9000); // let the CDN script load + world build + some frames

  const boot = await send('Runtime.evaluate', {
    expression: 'JSON.stringify({hasZen: !!window.__zen, fatal: document.getElementById("fatal").classList.contains("show"), loaderOut: document.getElementById("loader").classList.contains("out")})',
    returnByValue: true
  });
  console.log('BOOT:', boot.result && boot.result.result && boot.result.result.value);

  const stats = await send('Runtime.evaluate', {
    expression: 'JSON.stringify({calls: __zen.stats().calls, tris: __zen.tris(), geo: __zen.mem().geometries, tex: __zen.mem().textures})',
    returnByValue: true
  });
  console.log('STATS:', stats.result && stats.result.result && stats.result.result.value);

  for (const [name, hour] of TIMES) {
    await send('Runtime.evaluate', { expression: '__zen.setTime(' + hour + ')' });
    await sleep(2600); // let the damped lighting settle
    const shot = await send('Page.captureScreenshot', { format: 'png' });
    if (shot.result && shot.result.data) {
      fs.writeFileSync(OUT + '/' + name + '.png', Buffer.from(shot.result.data, 'base64'));
      console.log('shot', name);
    } else {
      console.log('shot FAILED', name);
    }
  }

  console.log('--- CONSOLE (' + logs.length + ') ---');
  logs.slice(0, 40).forEach(l => console.log(l));
  console.log('--- ERRORS (' + errors.length + ') ---');
  errors.slice(0, 40).forEach(e => console.log(e));

  ws.close();
  chrome.kill();
  process.exit(0);
})().catch(e => { console.error('driver error', e); chrome.kill(); process.exit(1); });

