function roof(b, cx, cy, cz, halfW, layers, cornerLift) {
  /* A hipped voxel roof: each course narrows going up, and the blocks
     near the corners stack a few extra so the eave sweeps upward. */
  for (var L = 0; L < layers; L++) {
    var r = halfW - L;
    var y = cy + L;
    for (var a = -r; a <= r; a++) {
      for (var c = -r; c <= r; c++) {
        var interior = Math.abs(a) < r - 1 && Math.abs(c) < r - 1;
        if (interior && L < layers - 1) continue;
        var ax = Math.abs(a), cz2 = Math.abs(c);
        var lift = 0;
        if (ax >= r - cornerLift && cz2 >= r - cornerLift) {
          var q = Math.min(3, Math.max(ax, cz2) - (r - cornerLift));
          lift = Math.round(q * q * 0.55);          /* 0, 1, 2, 3 */
        }
        for (var f = 0; f <= lift; f++) {
          b.at(cx + a, y + f, cz + c, (L === 0) ? pick(PAL.tileEdge) : pick(PAL.tile));
        }
      }
    }
  }
}

