// Interaction test: attract mode, drag-to-orbit, time slider, presets, pause.
const { spawn } = require('child_process');
const fs = require('fs'); const http = require('http');
const PORT = 9366, URL = 'file:///tmp/ocb/task-1-voxel-zen-garden/space-bunny/_test.html';
const sleep = ms => new Promise(r => setTimeout(r, ms));
const getJSON = p => new Promise((res, rej) => { http.get({ host: '127.0.0.1', port: PORT, path: p }, r => { let d = ''; r.on('data', c => d += c); r.on('end', () => { try { res(JSON.parse(d)); } catch (e) { rej(e); } }); }).on('error', rej); });
const chrome = spawn('chromium', ['--headless=new', '--no-sandbox', '--disable-dev-shm-usage', '--enable-unsafe-swiftshader', '--use-gl=angle', '--use-angle=swiftshader', '--hide-scrollbars', '--window-size=1024,640', '--remote-debugging-port=' + PORT, 'about:blank'], { stdio: 'ignore' });

const pass = [], fail = [];
function check(name, ok, detail) { (ok ? pass : fail).push(name + (detail ? '  [' + detail + ']' : '')); }

(async () => {
  let list = null; for (let i = 0; i < 60; i++) { try { list = await getJSON('/json/list'); if (list && list.length) break; } catch (e) { } await sleep(300); }
  const page = list.find(t => t.type === 'page') || list[0];
  const ws = new WebSocket(page.webSocketDebuggerUrl);
  let id = 0; const pending = new Map(); const errors = [];
  ws.onmessage = ev => { const m = JSON.parse(ev.data);
    if (m.id && pending.has(m.id)) { pending.get(m.id)(m); pending.delete(m.id); return; }
    if (m.method === 'Runtime.exceptionThrown') errors.push((m.params.exceptionDetails.exception && m.params.exceptionDetails.exception.description || m.params.exceptionDetails.text || '').slice(0, 160));
    if (m.method === 'Log.entryAdded' && m.params.entry.level === 'error') errors.push('LOG ' + m.params.entry.text.slice(0, 160)); };
  const send = (me, pr) => new Promise(r => { const i = ++id; pending.set(i, r); ws.send(JSON.stringify({ id: i, method: me, params: pr || {} })); });
  await new Promise(r => ws.onopen = r);
  await send('Runtime.enable'); await send('Log.enable'); await send('Page.enable');
  await send('Emulation.setDeviceMetricsOverride', { width: 1024, height: 640, deviceScaleFactor: 1, mobile: false });
  await send('Page.navigate', { url: URL });
  await sleep(9000);

  const ev = async e => { const r = await send('Runtime.evaluate', { expression: e, returnByValue: true }); return r.result && r.result.result ? r.result.result.value : undefined; };
  const camPos = () => ev('JSON.stringify(__zen.camera.position.toArray().map(function(v){return +v.toFixed(3)}))');
  const clock = () => ev('document.getElementById("clock").textContent');
  const sliderV = () => ev('document.getElementById("timeSlider").value');

  // ---- 1. attract mode runs with no input at all ----
  check('no fatal screen', (await ev('document.getElementById("fatal").classList.contains("show")')) === false);
  check('loader revealed', (await ev('document.getElementById("loader").classList.contains("out")')) === true);
  const c0 = await camPos(), k0 = await clock();
  await sleep(6000);
  const c1 = await camPos(), k1 = await clock();
  const d = Math.hypot(c1[0] - c0[0], c1[1] - c0[1], c1[2] - c0[2]);
  check('camera auto-orbits unattended', d > 0.5, 'moved ' + d.toFixed(2) + ' units');
  check('day cycle advances unattended', k0 !== k1, k0 + ' -> ' + k1);

  // ---- 2. drag to orbit ----
  const before = await camPos();
  await send('Input.dispatchMouseEvent', { type: 'mousePressed', x: 500, y: 300, button: 'left', buttons: 1, clickCount: 1 });
  for (let i = 1; i <= 6; i++) {
    await send('Input.dispatchMouseEvent', { type: 'mouseMoved', x: 500 + i * 22, y: 300 - i * 5, button: 'left', buttons: 1 });
    await sleep(90);
  }
  await send('Input.dispatchMouseEvent', { type: 'mouseReleased', x: 632, y: 270, button: 'left', buttons: 0, clickCount: 1 });
  await sleep(1500);
  const after = await camPos();
  const dd = Math.hypot(after[0] - before[0], after[1] - before[1], after[2] - before[2]);
  check('drag orbits the camera', dd > 3, 'moved ' + dd.toFixed(2) + ' units');
  check('drag does not break framing', after[1] > 3 && Math.hypot(after[0], after[2]) < 90, 'y=' + after[1].toFixed(1));

  // auto-orbit should blend back in after the idle timeout
  await sleep(9000);
  const resumed = await camPos();
  const rd = Math.hypot(resumed[0] - after[0], resumed[1] - after[1], resumed[2] - after[2]);
  check('auto-orbit resumes after idle', rd > 0.4, 'drifted ' + rd.toFixed(2));

  // ---- 3. time slider ----
  await ev('(function(){var s=document.getElementById("timeSlider");s.value="3.5";s.dispatchEvent(new Event("input",{bubbles:true}));})()');
  await sleep(1200);
  check('slider drives the clock', (await clock()) === '03:30', await clock());
  check('slider pauses the cycle', (await ev('document.getElementById("autoTxt").textContent')) === 'Manual');
  check('slider position reflects value', Math.abs(parseFloat(await sliderV()) - 3.5) < 0.2, await sliderV());

  // ---- 4. presets ----
  await ev('document.querySelector("#presets button[data-h=\'22.5\']").click()');
  await sleep(1200);
  check('night preset sets the time', (await clock()) === '22:30', await clock());
  await ev('document.querySelector("#presets button[data-h=\'6.2\']").click()');
  await sleep(1200);
  check('dawn preset sets the time', (await clock()) === '06:12', await clock());

  // ---- 5. play / pause ----
  await ev('document.getElementById("playBtn").click()');
  await sleep(600);
  check('pause button toggles to manual', (await ev('document.getElementById("autoTxt").textContent')) === 'Manual');
  const p0 = await clock(); await sleep(2500); const p1 = await clock();
  check('clock is frozen while paused', p0 === p1, p0 + ' / ' + p1);
  await ev('document.getElementById("playBtn").click()');
  await sleep(600);
  check('resume returns to auto', (await ev('document.getElementById("autoTxt").textContent')) === 'Auto cycle');

  // ---- 6. zoom ----
  const z0 = Math.hypot(...(await camPos()).slice(0, 2));
  await send('Input.dispatchMouseEvent', { type: 'mouseWheel', x: 500, y: 300, deltaX: 0, deltaY: 240 });
  await sleep(1500);
  const cp = (await camPos()).slice(0, 2);
  check('wheel zooms', Math.hypot(cp[0], cp[1]) !== z0, 'changed');

  console.log('PASS (' + pass.length + ')'); pass.forEach(p => console.log('  + ' + p));
  console.log('FAIL (' + fail.length + ')'); fail.forEach(p => console.log('  - ' + p));
  console.log('ERRORS (' + errors.length + ')'); errors.slice(0, 10).forEach(e => console.log('  ! ' + e));
  ws.close(); chrome.kill(); process.exit(fail.length ? 1 : 0);
})().catch(e => { console.error(e); chrome.kill(); process.exit(1); });

