      out.push([+v.x.toFixed(2), +v.y.toFixed(2), +v.z.toFixed(2)]);
    }
    return JSON.stringify({
      sample: out,
      count: koiMesh.count,
      hasColor: !!koiMesh.instanceColor,
      col0: koiMesh.instanceColor ? [koiMesh.instanceColor.array[0], koiMesh.instanceColor.array[1], koiMesh.instanceColor.array[2]] : null,
      visible: koiMesh.visible,
      inScene: !!koiMesh.parent,
      depthTest: matKoi.depthTest,
      waterY: WATER_Y,
      pondFloorY: gy(POND_K) + VS / 2
    });
  },
  setWaterVisible: function (v) { water.visible = v; },
  /* force the damped grade to convergence immediately (test harness only) */
  snap: function (h) {
    ui.auto = false; ui.time = h; ui.idle = -1e6; syncPlayBtn();
    for (var i = 0; i < 200; i++) updateSky(h, 0.1);
  },

