// Final smoke test on the delivered file (debug hooks removed): boots from
// file://, renders unattended, no console errors, pixel content is real.
const { spawn } = require('child_process');
const fs = require('fs'); const http = require('http');
const PORT = 9377, URL = 'file:///tmp/ocb/task-1-voxel-zen-garden/space-bunny/_test.html';
const OUT = '/tmp/ocb/task-1-voxel-zen-garden/space-bunny/_shots';
const sleep = ms => new Promise(r => setTimeout(r, ms));
const getJSON = p => new Promise((res, rej) => { http.get({ host: '127.0.0.1', port: PORT, path: p }, r => { let d = ''; r.on('data', c => d += c); r.on('end', () => { try { res(JSON.parse(d)); } catch (e) { rej(e); } }); }).on('error', rej); });
const chrome = spawn('chromium', ['--headless=new', '--no-sandbox', '--disable-dev-shm-usage', '--enable-unsafe-swiftshader', '--use-gl=angle', '--use-angle=swiftshader', '--hide-scrollbars', '--window-size=1280,800', '--remote-debugging-port=' + PORT, 'about:blank'], { stdio: 'ignore' });
(async () => {
  let list = null; for (let i = 0; i < 60; i++) { try { list = await getJSON('/json/list'); if (list && list.length) break; } catch (e) { } await sleep(300); }
  const page = list.find(t => t.type === 'page') || list[0];
  const ws = new WebSocket(page.webSocketDebuggerUrl);
  let id = 0; const pending = new Map(); const errors = [];
  ws.onmessage = ev => { const m = JSON.parse(ev.data);
    if (m.id && pending.has(m.id)) { pending.get(m.id)(m); pending.delete(m.id); return; }
    if (m.method === 'Runtime.exceptionThrown') errors.push('EXC ' + ((m.params.exceptionDetails.exception && m.params.exceptionDetails.exception.description) || m.params.exceptionDetails.text || '').slice(0, 200));
    if (m.method === 'Log.entryAdded' && m.params.entry.level === 'error') errors.push('LOG ' + m.params.entry.text.slice(0, 200));
    if (m.method === 'Runtime.consoleAPICalled' && m.params.type === 'error') errors.push('CON ' + (m.params.args || []).map(a => a.value || a.description || '').join(' ').slice(0, 200)); };
  const send = (me, pr) => new Promise(r => { const i = ++id; pending.set(i, r); ws.send(JSON.stringify({ id: i, method: me, params: pr || {} })); });
  await new Promise(r => ws.onopen = r);
  await send('Runtime.enable'); await send('Log.enable'); await send('Page.enable');
  await send('Emulation.setDeviceMetricsOverride', { width: 1280, height: 800, deviceScaleFactor: 1, mobile: false });
  await send('Page.startScreencast', { format: 'jpeg', quality: 20, maxWidth: 64, maxHeight: 40, everyNthFrame: 1 });
  await send('Page.navigate', { url: URL });
  await sleep(14000);
  const ev = async e => { const r = await send('Runtime.evaluate', { expression: e, returnByValue: true }); return r.result && r.result.result ? r.result.result.value : undefined; };

  const state = await ev('JSON.stringify({ fatal: document.getElementById("fatal").classList.contains("show"), loaderOut: document.getElementById("loader").classList.contains("out"), panelIn: document.getElementById("panel").classList.contains("in"), titleIn: document.getElementById("title").classList.contains("in"), clock: document.getElementById("clock").textContent, canvas: !!document.querySelector("canvas"), globals: Object.keys(window).filter(function(k){return k.indexOf("__")===0}) })');
  console.log('STATE:', state);

  const shot = await send('Page.captureScreenshot', { format: 'png' });
  if (shot.result && shot.result.data) {
    fs.writeFileSync(OUT + '/final.png', Buffer.from(shot.result.data, 'base64'));
    console.log('final.png written');
  }
  console.log('ERRORS (' + errors.length + ')'); errors.forEach(e => console.log('  ! ' + e));
  ws.close(); chrome.kill(); process.exit(0);
})().catch(e => { console.error(e); chrome.kill(); process.exit(1); });

